// A stand-in for a Locator: an object whose contents change without the const
// that points at it ever being reassigned.
const pretendLocator = { selector: "input[type='email']", timesClicked: 0 };

function pretendClick(loc: typeof pretendLocator) {
  loc.timesClicked++; // mutates the object; no reassignment
}

pretendClick(pretendLocator);
pretendClick(pretendLocator);
console.log(pretendLocator); // same const, changed contents

